<!doctype html><html><head><meta charset="utf-8"><title>Purchase Order {{ $order->number }}</title><style>body{font-family:Arial,sans-serif;color:#12233f;margin:32px}header{display:flex;justify-content:space-between;gap:24px;border-bottom:2px solid #2563eb;padding-bottom:16px}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{border:1px solid #ccd7e5;padding:8px;text-align:left}th{background:#f1f5f9}h1{margin:0 0 4px}.muted{color:#64748b}.meta{margin-top:20px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.totals{margin:24px 0 0 auto;max-width:320px}.totals div{display:flex;justify-content:space-between;padding:5px 0}.grand{border-top:2px solid #12233f;font-weight:700;font-size:18px;margin-top:5px;padding-top:10px}@media print{body{margin:12mm}button{display:none}}</style></head><body><header><div><h1>Purchase Order {{ $order->number }}</h1><p class="muted">{{ $order->company?->legal_name ?: $order->company?->name ?: 'Company' }} @if($order->company?->street_address), {{ $order->company->street_address }} @endif</p></div><div><strong>{{ ucfirst($order->state) }}</strong><p class="muted">Supplier: {{ $order->supplier->name }}</p></div></header><div class="meta"><div><strong>Order date</strong><br>{{ $order->order_date?->format('Y-m-d') ?: $order->created_at?->format('Y-m-d') }}</div><div><strong>Expected delivery</strong><br>{{ $order->expected_at?->format('Y-m-d') ?: 'Not specified' }}</div><div><strong>Branch / warehouse</strong><br>{{ $order->branch?->name ?: 'All branches' }} / {{ $order->warehouse?->name ?: 'Not specified' }}</div></div><table><thead><tr><th>Product</th><th>SKU</th><th>Ordered</th><th>Received</th><th>Unit price</th><th>Discount</th><th>Tax</th><th>Line total</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->variant?->product?->name ?: 'Product' }}@if($item->description)<br><span class="muted">{{ $item->description }}</span>@endif</td><td>{{ $item->variant?->sku ?: $item->variant_id }}</td><td>{{ $item->ordered_quantity }}</td><td>{{ $item->received_quantity }}</td><td>{{ $item->unit_price }}</td><td>{{ $item->discount_amount ?: '0.000000' }}</td><td>{{ $item->tax_amount ?: '0.000000' }}</td><td>{{ $item->line_total ?: 'Unavailable' }}</td></tr>@endforeach</tbody></table><div class="totals"><div><span>Subtotal</span><strong>{{ $order->subtotal ?: 'Unavailable' }}</strong></div><div><span>Discount</span><strong>{{ $order->discount_total ?: 'Unavailable' }}</strong></div><div><span>Tax</span><strong>{{ $order->tax_total ?: 'Unavailable' }}</strong></div><div><span>Shipping</span><strong>{{ $order->shipping_total ?: '0.000000' }}</strong></div><div class="grand"><span>Grand total</span><strong>{{ $order->grand_total ?: ($order->base_total ?: 'Unavailable') }} {{ $order->currency?->code ?: $order->company?->base_currency }}</strong></div></div><p class="muted">This document reflects the recorded purchase order status. Draft and submitted orders are not approved.</p><script>window.print()</script></body></html>
